import sys,json
for line in sys.stdin:
    line=line.strip()
    if not line or line.startswith('{\"type\":\"stats\"'): continue
    try: d=json.loads(line)
    except: continue
    if 'currentPatchSet' not in d: continue
    cps=d['currentPatchSet']
    print('  ps', cps['number'], '| revision', cps['revision'][:10], '| parents', [p[:10] for p in cps.get('parents',[])])
    want={'Vela-Precheck','CI-Checks','Presubmit-Ready','Vela-Presubmit-Verified','Code-Review'}
    for a in cps.get('approvals',[]):
        if a['type'] in want:
            print('   ', a['type'], a['value'], 'by', a.get('by',{}).get('username','?'))
" 2>&1; done
